# Builds the modules generated by a "source" export into DLLs loadable by suyu
# (recompiled_<module>.dll / recompiled_image.dll for main), with clang-cl.
#
# It is the same as what the exporter does in "build" mode (game_export.cpp: clang-cl +
# Ninja inside the vcvars64 environment), but module by module, timing each one
# and leaving the result where run-hybrid.ps1 looks for it:
#   <mk8-recomp>\build\recomp\<Target>\<module>\recompiled_*.dll
#
#   .\recomp\scripts\build-modules.ps1 -Export '<root>\exports\pla-hybrid-source-roots' -Target pla
#   .\recomp\scripts\build-modules.ps1 ... -Modules rtld,sdk -Jobs 4 -Compiler msvc
#
# -Toolchain portable: no VS Build Tools, Windows SDK or CMake/Ninja. Uses the tools/toolchain
# package (clang-cl + lld-link + our own headers and import libraries) and its driver
# build_modules.py; same output and same flags. See docs/port/TOOLCHAIN.md.
#   .\recomp\scripts\build-modules.ps1 -Export <export> -Toolchain portable -ToolchainDir <root>\toolchain-portable\recomp-toolchain
# With the portable toolchain the big units are split (-SplitMB, default 8 MB of C per part) and -Jobs 0
# (default) lets the driver run as many compiles as logical cores and free RAM allow (memory-aware).
# -SplitMB 0 -Jobs 3 = the previous whole-unit build.

[CmdletBinding()]
param(
    [Parameter(Mandatory)][string]$Export,
    [string]$Target = 'pla',
    [string[]]$Modules = @(),
    [int]$Jobs = 0,
    [ValidateSet('clang-cl', 'msvc')][string]$Compiler = 'clang-cl',
    # Output folder (default <mk8-recomp>\build\recomp\<Target>); the launcher uses its own work folder.
    [string]$BuildRoot = '',
    # 'vs' = vcvars + CMake + Ninja (as before); 'portable' = tools/toolchain without VS.
    [ValidateSet('vs', 'portable')][string]$Toolchain = 'vs',
    [string]$ToolchainDir = '',
    # Portable toolchain only: split units bigger than 1.5x this many MB of C (0 = compile whole units).
    [double]$SplitMB = 8,
    # Portable toolchain only: target ISA (x86-64, x86-64-v2, x86-64-v3 or auto); empty = build_modules.py's default.
    [string]$Isa = '',
    # Portable toolchain only: optimize with this clang profile (.profdata, PGO); empty = no profile.
    [string]$ProfileUse = ''
)

$ErrorActionPreference = 'Stop'
. (Join-Path $PSScriptRoot 'env.ps1')
$exefs = Get-ChildItem -LiteralPath $Export -Recurse -Directory -Filter exefs |
         Where-Object { $_.Parent.Name -eq 'aot_cache' } | Select-Object -First 1
if (-not $exefs) { throw "no aot_cache\exefs under $Export" }
if (-not $Modules) {
    $Modules = Get-ChildItem -LiteralPath $exefs.FullName -Directory |
               Where-Object { Test-Path -LiteralPath (Join-Path $_.FullName 'CMakeLists.txt') } |
               ForEach-Object Name
}
$buildRoot = if ($BuildRoot) { $BuildRoot } else { Join-Path $MK8R_ROOT_DIR "build\recomp\$Target" }
$logDir = Join-Path $PLA_RECOMP_ROOT 'logs'
New-Item -ItemType Directory -Force -Path $buildRoot, $logDir | Out-Null
$clang = 'C:/Program Files/LLVM/bin/clang-cl.exe'
$results = @()

if ($Toolchain -eq 'portable') {
    $tc = if ($ToolchainDir) { $ToolchainDir } else { Join-Path $PLA_RECOMP_ROOT 'toolchain-portable\recomp-toolchain' }
    if (-not (Test-Path -LiteralPath (Join-Path $tc 'bin\clang-cl.exe'))) { throw "no portable toolchain in $tc (tools\toolchain\build-toolchain.ps1)" }
    # The driver next to these scripts (newer than the package's copy when both exist; it needs split_units.py).
    $py = Join-Path $PSScriptRoot '..\..\tools\toolchain\build_modules.py'
    if (-not (Test-Path -LiteralPath (Join-Path $PSScriptRoot '..\..\tools\toolchain\split_units.py'))) { $py = Join-Path $tc 'build_modules.py' }
    $pyArgs = @('-I', $py, '--out', $buildRoot, '--toolchain', $tc)
    if (Select-String -LiteralPath $py -Pattern '--split-mb' -SimpleMatch -Quiet) { $pyArgs += @('--split-mb', "$SplitMB") }
    if ($Isa -and (Select-String -LiteralPath $py -Pattern '--isa' -SimpleMatch -Quiet)) { $pyArgs += @('--isa', $Isa) }
    if ($ProfileUse) { $pyArgs += @('--profile-use', $ProfileUse) }
    foreach ($m in $Modules) { $pyArgs += @('--module-dir', (Join-Path $exefs.FullName $m)) }
    if ($Jobs -gt 0) { $pyArgs += @('--jobs', "$Jobs") }
    $sw = [Diagnostics.Stopwatch]::StartNew()
    & python @pyArgs
    if ($LASTEXITCODE -ne 0) { throw "build_modules.py failed ($LASTEXITCODE); see $buildRoot\build_modules.log" }
    Write-Host ("== portable toolchain: {0:n1} min" -f $sw.Elapsed.TotalMinutes)
    return
}

foreach ($m in $Modules) {
    $src = Join-Path $exefs.FullName $m
    $bld = Join-Path $buildRoot $m
    $tgt = if ($m -eq 'main') { 'recompiled_image' } else { "recompiled_$m" }
    $log = Join-Path $logDir "build-module-$Target-$m.log"
    $cfg = "-S `"$src`" -B `"$bld`" -G Ninja -DCMAKE_BUILD_TYPE=Release -DRECOMP_BUILD_STATIC_LIB=OFF"
    if ($Compiler -eq 'clang-cl') { $cfg += " -DCMAKE_C_COMPILER=`"$clang`"" }
    if ($Jobs -gt 0) { $cfg += " -DRECOMP_JOBS=$Jobs" }
    $cSize = (Get-ChildItem -LiteralPath (Join-Path $src 'src') -File | Measure-Object Length -Sum).Sum
    Write-Host ("== {0}: {1:n0} MB of C, target {2}" -f $m, ($cSize / 1MB), $tgt)
    $bat = Join-Path $env:TEMP "build-module-$PID.cmd"
    Set-Content -LiteralPath $bat -Encoding ascii -Value @"
@call "$env:MK8R_VCVARS" >nul 2>&1
cmake $cfg || exit /b 1
cmake --build "$bld" --target $tgt || exit /b 1
"@
    $sw = [Diagnostics.Stopwatch]::StartNew()
    $p = Start-Process cmd.exe -ArgumentList '/c', "`"$bat`"" -NoNewWindow -Wait -PassThru `
            -RedirectStandardOutput $log -RedirectStandardError "$log.err"
    $sw.Stop()
    $dll = Get-ChildItem -LiteralPath $bld -Recurse -Filter '*.dll' -File -ErrorAction SilentlyContinue |
           Select-Object -First 1
    $r = [pscustomobject]@{
        Module = $m; Exit = $p.ExitCode; Minutes = [math]::Round($sw.Elapsed.TotalMinutes, 1)
        C_MB = [math]::Round($cSize / 1MB); Dll = if ($dll) { $dll.Name } else { '' }
        Dll_MB = if ($dll) { [math]::Round($dll.Length / 1MB, 1) } else { 0 }
    }
    $results += $r
    $r | Format-Table -AutoSize | Out-Host
    if ($p.ExitCode -ne 0) { Write-Warning "$m failed; see $log and $log.err"; Get-Content $log -Tail 20 | Out-Host }
}
$results | Export-Csv -NoTypeInformation -Path (Join-Path $logDir "build-modules-$Target.csv")
$results | Format-Table -AutoSize
